def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def bands(size, separators):
        result = []
        start = 0
        for p in separators + [size]:
            if start < p:
                result.append((start, p))
            start = p + 1
        return result

    rb = bands(h, sep_rows)
    cb = bands(w, sep_cols)

    sep_colors = {grid[r][0] for r in sep_rows}
    sep_colors |= {grid[0][c] for c in sep_cols}

    freq = {}
    for r0, r1 in rb:
        for c0, c1 in cb:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    color = grid[r][c]
                    if color not in sep_colors:
                        freq[color] = freq.get(color, 0) + 1

    background = max(freq, key=freq.get)
    special = [color for color in freq if color != background]
    marker = special[0] if special else None

    out = []
    for r0, r1 in rb:
        row = []
        for c0, c1 in cb:
            count = sum(
                grid[r][c] == marker
                for r in range(r0, r1)
                for c in range(c0, c1)
            ) if marker is not None else 0
            row.append(1 if count >= 2 else background)
        out.append(row)
    return out
